  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tiga buah resistor R1 = 5 Ω, R2 = 10 Ω, dan R3 = 15 Ω dihubungkan secara seri dengan sumber tegangan 30 V. Berapakah tegangan jatuh (voltage drop) pada resistor R2?','[{"key": "A", "text": "5 V"}, {"key": "B", "text": "10 V"}, {"key": "C", "text": "15 V"}, {"key": "D", "text": "30 V"}]'::jsonb,'B','Untuk mencari tegangan jatuh pada salah satu resistor dalam rangkaian seri, kita harus terlebih dahulu mencari arus total yang mengalir dalam rangkaian. Pertama, hitung hambatan totalnya: Rtotal​=R1​+R2​+R3​=5Ω+10Ω+15Ω=30Ω. Selanjutnya, hitung arus total yang mengalir: Itotal​=Vsumber​/Rtotal​=30V/30Ω=1A. Akhirnya, tegangan jatuh pada R2 adalah VR2​=Itotal​×R2​=1A×10Ω=10V.','AKDING',3);
