  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah motor 3 fasa terhubung bintang (Y) ke sumber 380 V (tegangan jala-jala) dan menarik arus 10 A dengan faktor daya 0.85 (tertinggal). Daya nyata (P) yang dikonsumsi motor adalah...','[{"key": "A", "text": "3.23 kW"}, {"key": "B", "text": "3.80 kW"}, {"key": "C", "text": "5.60 kW"}, {"key": "D", "text": "6.58 kW"}]'::jsonb,'C','Rumus untuk menghitung daya nyata (aktif) pada sistem 3 fasa yang seimbang adalah P=3​×Vline​×Iline​×cos(ϕ). Dengan data yang diberikan, perhitungannya adalah P=1.732×380V×10A×0.85≈5594W, yang setara dengan 5.60kW.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari koreksi faktor daya pada sistem tenaga listrik industri adalah...','[{"key": "A", "text": "Meningkatkan tegangan sistem."}, {"key": "B", "text": "Mengurangi rugi-rugi daya pada saluran dan menghindari denda dari PLN."}, {"key": "C", "text": "Menambah daya reaktif pada sistem."}, {"key": "D", "text": "Menurunkan frekuensi sistem."}]'::jsonb,'B','Faktor daya yang rendah menandakan adanya daya reaktif yang besar. Untuk menyalurkan daya nyata yang sama, arus total pada saluran harus lebih besar, yang menyebabkan rugi-rugi daya (Prugi​=I2R) yang lebih besar pada kabel. PLN sering memberlakukan denda (biaya kelebihan pemakaian kVARh) untuk industri dengan faktor daya rendah karena membebani jaringan mereka.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan salah satu kelebihan dari hubungan delta (Δ) dibandingkan hubungan bintang (Y)?','[{"key": "A", "text": "Membutuhkan kawat netral."}, {"key": "B", "text": "Tegangan fasa sama dengan tegangan saluran."}, {"key": "C", "text": "Arus fasa lebih besar dari arus saluran."}, {"key": "D", "text": "Lebih tahan terhadap gangguan fasa-ke-tanah."}]'::jsonb,'B','Pada hubungan delta (segitiga), setiap ujung lilitan fasa terhubung langsung ke dua saluran yang berbeda. Akibatnya, tegangan yang melintasi setiap fasa (Vfasa​) sama dengan tegangan antar saluran (Vsaluran​). Sebaliknya, pada hubungan bintang, hubungan tegangannya adalah Vsaluran​=3​×Vfasa​.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah beban 3 fasa terhubung delta (Δ) memiliki impedansi 25 Ω per fasa dan terhubung ke sumber tegangan 400 V. Besar arus saluran (line current) adalah...','[{"key": "A", "text": "16.0 A"}, {"key": "B", "text": "27.7 A"}, {"key": "C", "text": "48.0 A"}, {"key": "D", "text": "9.2 A"}]'::jsonb,'B','Untuk beban terhubung delta, pertama kita hitung arus yang mengalir di setiap fasa beban, kemudian kita hitung arus yang mengalir di saluran. Arus fasa dihitung terlebih dahulu: Ifasa​=Vfasa​/Zfasa​=400V/25Ω=16A. Untuk hubungan delta, arus saluran adalah Isaluran​=3​×Ifasa​=1.732×16A≈27.7A.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada transformator ideal, jika rasio lilitan sekunder terhadap primer adalah 1:5, dan tegangan primer adalah 1000 V, maka tegangan sekunder adalah...','[{"key": "A", "text": "100 V"}, {"key": "B", "text": "200 V"}, {"key": "C", "text": "5000 V"}, {"key": "D", "text": "25000 V"}]'::jsonb,'B','Hubungan antara tegangan dan jumlah lilitan pada transformator ideal adalah berbanding lurus, sesuai rumus Vp​/Vs​=Np​/Ns​. Maka, tegangan sekunder dapat dihitung sebagai Vs​=Vp​×(Ns​/Np​)=1000V×(1/5)=200V. Ini adalah transformator step-down.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dua jenis rugi-rugi utama yang terjadi pada transformator nyata adalah...','[{"key": "A", "text": "Rugi tegangan dan rugi arus."}, {"key": "B", "text": "Rugi primer dan rugi sekunder."}, {"key": "C", "text": "Rugi inti (besi) dan rugi tembaga."}, {"key": "D", "text": "Rugi fluks dan rugi histeresis."}]'::jsonb,'C','Rugi-rugi pada transformator nyata terdiri dari Rugi Inti (Besi), yang relatif konstan selama transformator bertegangan, dan Rugi Tembaga (I2R), yang sebanding dengan kuadrat arus beban dan terjadi pada lilitan tembaga.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah transformator 100 kVA memiliki rugi tembaga 1200 W dan rugi inti 750 W pada beban penuh. Efisiensi transformator pada beban penuh dengan faktor daya 0.9 adalah sekitar...','[{"key": "A", "text": "95.5%"}, {"key": "B", "text": "97.9%"}, {"key": "C", "text": "98.2%"}, {"key": "D", "text": "99.1%"}]'::jsonb,'B','Efisiensi (η) adalah perbandingan antara daya output dengan daya input. Daya output adalah Pout​=S×Faktor Daya=100,000VA×0.9=90,000W. Total rugi daya adalah Prugi​=1200W+750W=1950W. Daya inputnya adalah Pin​=Pout​+Prugi​=90,000W+1950W=91,950W. Maka efisiensinya adalah η=(Pout​/Pin​)×100%=(90000/91950)×100%≈97.9%.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah syarat berikut yang TIDAK harus dipenuhi agar dua transformator dapat dioperasikan secara paralel?','[{"key": "A", "text": "Rasio tegangan harus sama."}, {"key": "B", "text": "Polaritas harus sama."}, {"key": "C", "text": "Impedansi per unit harus sama."}, {"key": "D", "text": "Kapasitas kVA harus sama."}]'::jsonb,'D','Tiga syarat utama (wajib) agar trafo dapat diparalel adalah: rasio tegangan sama, polaritas sama, dan impedansi per unit (pu) sama. Jika kapasitas kVA berbeda tetapi impedansi pu sama, maka beban akan terbagi secara proporsional sesuai kapasitas masing-masing trafo. Jadi, kapasitas kVA tidak wajib sama.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Nilai impedansi transformator sangat penting dalam analisis sistem tenaga karena digunakan untuk...','[{"key": "A", "text": "Menghitung efisiensi transformator."}, {"key": "B", "text": "Menentukan rasio lilitan."}, {"key": "C", "text": "Membatasi dan menghitung arus hubung singkat."}, {"key": "D", "text": "Mengukur suhu operasi transformator."}]'::jsonb,'C','Impedansi internal transformator adalah faktor utama yang membatasi seberapa besar arus yang dapat mengalir saat terjadi hubung singkat. Nilai ini sangat krusial untuk menentukan kapasitas pemutusan (breaking capacity) dari peralatan proteksi seperti pemutus tenaga (PMT).','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jatuh tegangan (voltage drop) pada saluran transmisi terutama disebabkan oleh...','[{"key": "A", "text": "Frekuensi sistem."}, {"key": "B", "text": "Impedansi saluran (resistansi dan reaktansi)."}, {"key": "C", "text": "Suhu lingkungan."}, {"key": "D", "text": "Ketinggian menara transmisi."}]'::jsonb,'B','Setiap konduktor memiliki impedansi (Z), yang merupakan gabungan dari resistansi (R) dan reaktansi (X). Ketika arus (I) mengalir melaluinya, terjadi jatuh tegangan sebesar Vdrop​=I×Z. Semakin panjang saluran dan semakin besar arus, semakin besar pula jatuh tegangannya.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Faktor beban (load factor) didefinisikan sebagai perbandingan antara...','[{"key": "A", "text": "Beban puncak dan beban rata-rata."}, {"key": "B", "text": "Beban rata-rata dan beban puncak."}, {"key": "C", "text": "Beban sesaat dan beban terpasang."}, {"key": "D", "text": "Beban terpasang dan beban puncak."}]'::jsonb,'B','Faktor beban adalah indikator seberapa efektif kapasitas sistem digunakan. Rumusnya adalah perbandingan antara beban rata-rata dengan beban puncak dalam periode waktu tertentu.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Mengapa faktor beban yang tinggi lebih diinginkan dalam sistem tenaga listrik?','[{"key": "A", "text": "Menandakan penggunaan peralatan yang efisien dan biaya per kWh yang lebih rendah."}, {"key": "B", "text": "Menunjukkan bahwa beban puncak sangat tinggi."}, {"key": "C", "text": "Mengurangi kebutuhan kapasitas pembangkit."}, {"key": "D", "text": "Meningkatkan rugi-rugi transmisi."}]'::jsonb,'A','Faktor beban yang tinggi (mendekati 1) berarti beban listrik relatif konstan. Ini memungkinkan pembangkit dan jaringan beroperasi pada titik efisiensi optimalnya secara terus-menerus, sehingga biaya produksi per kWh menjadi lebih rendah.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan utama antara jaringan distribusi primer dan sekunder terletak pada...','[{"key": "A", "text": "Jenis konduktor yang digunakan."}, {"key": "B", "text": "Tingkat tegangan operasinya."}, {"key": "C", "text": "Panjang jaringan."}, {"key": "D", "text": "Jenis beban yang dilayani."}]'::jsonb,'B','Jaringan Primer adalah Jaringan Tegangan Menengah (JTM), misalnya 20 kV, yang mendistribusikan daya dari gardu induk ke trafo distribusi. Jaringan Sekunder adalah Jaringan Tegangan Rendah (JTR), misalnya 220/380 V, yang mendistribusikan daya dari trafo ke pelanggan akhir.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Selain kerugian I²R (akibat resistansi), kerugian daya yang signifikan pada saluran transmisi tegangan ekstra tinggi adalah...','[{"key": "A", "text": "Rugi dielektrik."}, {"key": "B", "text": "Rugi eddy current."}, {"key": "C", "text": "Rugi korona."}, {"key": "D", "text": "Rugi mekanis."}]'::jsonb,'C','Pada saluran transmisi tegangan ekstra tinggi, gradien tegangan di permukaan konduktor sangat tinggi sehingga mampu mengionisasi udara di sekitarnya. Proses ini menghasilkan pelepasan energi berupa cahaya dan suara, yang merupakan bentuk rugi-rugi daya yang disebut rugi korona.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama dari relay proteksi adalah...','[{"key": "A", "text": "Memutus rangkaian secara langsung saat terjadi gangguan."}, {"key": "B", "text": "Mendeteksi kondisi abnormal/gangguan dan memberikan sinyal trip ke pemutus tenaga."}, {"key": "C", "text": "Mengukur besaran listrik seperti arus, tegangan, dan daya."}, {"key": "D", "text": "Mengisolasi peralatan untuk pemeliharaan."}]'::jsonb,'B','Relay proteksi berfungsi sebagai sensor cerdas. Ia terus-menerus memonitor parameter sistem (arus, tegangan, dll). Jika parameter tersebut keluar dari batas normal, relay akan mengirimkan sinyal perintah (sinyal trip) ke Pemutus Tenaga (PMT) untuk membuka rangkaian.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Zona proteksi (zone of protection) adalah...','[{"key": "A", "text": "Area di sekitar gardu induk yang harus steril."}, {"key": "B", "text": "Batasan geografis yang dilindungi oleh satu sistem proteksi."}, {"key": "C", "text": "Jarak aman bagi pekerja dari peralatan bertegangan."}, {"key": "D", "text": "Area di mana relay tidak dapat mendeteksi gangguan."}]'::jsonb,'B','Setiap perangkat proteksi dirancang untuk melindungi bagian tertentu dari sistem tenaga, seperti satu transformator atau satu ruas saluran transmisi. Area yang dicakup oleh perlindungan ini disebut zona proteksi.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip kerja dari proteksi arus lebih (overcurrent protection) adalah...','[{"key": "A", "text": "Bekerja ketika tegangan melebihi batas."}, {"key": "B", "text": "Bekerja ketika arus melebihi nilai setting dalam waktu tertentu."}, {"key": "C", "text": "Bekerja ketika frekuensi turun di bawah batas."}, {"key": "D", "text": "Bekerja ketika terjadi perbedaan arus antara dua titik."}]'::jsonb,'B','Arus gangguan (seperti hubung singkat) selalu jauh lebih besar dari arus beban normal. Relay arus lebih diatur (di-setting) untuk bekerja jika arus yang terukur melebihi nilai ambang batas tersebut, seringkali dengan elemen waktu tunda untuk menghindari trip yang tidak perlu.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari sistem pentanahan (grounding) pada peralatan listrik adalah...','[{"key": "A", "text": "Meningkatkan efisiensi energi."}, {"key": "B", "text": "Menyediakan jalur balik untuk arus netral."}, {"key": "C", "text": "Untuk keselamatan, yaitu membatasi tegangan berlebih dan menyediakan jalur aman bagi arus gangguan."}, {"key": "D", "text": "Menstabilkan frekuensi sistem."}]'::jsonb,'C','Pentanahan (grounding) menyediakan jalur berimpedansi rendah ke tanah agar arus gangguan dapat mengalir dengan deras, sehingga cukup besar untuk mengaktifkan perangkat proteksi. Ini juga memastikan bodi peralatan tidak bertegangan tinggi yang berbahaya bagi manusia.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan fundamental antara Pemutus Tenaga (PMT/Circuit Breaker) dan Pemisah (PMS/Isolator) adalah...','[{"key": "A", "text": "PMT bekerja lebih cepat daripada PMS."}, {"key": "B", "text": "PMT dapat memutus arus beban dan arus gangguan, sedangkan PMS hanya boleh dioperasikan pada kondisi tanpa beban."}, {"key": "C", "text": "PMT digunakan di tegangan tinggi, PMS di tegangan rendah."}, {"key": "D", "text": "PMS memiliki kemampuan pemadaman busur api, sedangkan PMT tidak."}]'::jsonb,'B','Perbedaan krusial terletak pada kemampuan memadamkan busur api listrik. PMT dilengkapi dengan media pemadam busur api (seperti gas SF6 atau vakum), sedangkan PMS tidak, sehingga berbahaya jika dibuka saat ada aliran arus.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Konversi langsung energi cahaya matahari menjadi energi listrik oleh sel surya dikenal sebagai efek...','[{"key": "A", "text": "Fotolistrik."}, {"key": "B", "text": "Fotovoltaik."}, {"key": "C", "text": "Termoelektrik."}, {"key": "D", "text": "Piezoelektrik."}]'::jsonb,'B','Efek fotovoltaik adalah proses di mana sebuah material semikonduktor (seperti silikon pada sel surya) menghasilkan tegangan listrik ketika terpapar foton dari cahaya matahari. Ini berbeda dari efek fotolistrik, yang lebih umum merujuk pada pelepasan elektron dari permukaan logam.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sistem PLTS yang terhubung ke jaringan (on-grid), fungsi utama inverter adalah...','[{"key": "A", "text": "Menyimpan energi listrik ke baterai."}, {"key": "B", "text": "Menaikkan tegangan DC dari panel surya."}, {"key": "C", "text": "Mengubah daya DC dari panel surya menjadi daya AC yang sinkron dengan jaringan."}, {"key": "D", "text": "Melindungi panel surya dari petir."}]'::jsonb,'C','Panel surya menghasilkan listrik arus searah (DC), sedangkan jaringan listrik publik menggunakan arus bolak-balik (AC). Fungsi inverter adalah melakukan konversi dari DC ke AC dan menyinkronkan tegangan, frekuensi, serta fasa dari outputnya agar sama persis dengan jaringan PLN.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sistem energi hybrid (misalnya PLTS-Diesel) dirancang untuk...','[{"key": "A", "text": "Mengurangi biaya instalasi awal."}, {"key": "B", "text": "Hanya menggunakan satu sumber energi."}, {"key": "C", "text": "Meningkatkan keandalan pasokan listrik dengan mengkombinasikan beberapa sumber energi."}, {"key": "D", "text": "Mengurangi efisiensi sistem secara keseluruhan."}]'::jsonb,'C','Sistem hybrid menggabungkan kelebihan dari berbagai sumber energi untuk menutupi kekurangan masing-masing. Contohnya, PLTS yang tidak bisa menghasilkan listrik di malam hari dapat didukung oleh generator diesel atau baterai untuk memastikan pasokan listrik tetap tersedia.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu tantangan teknis terbesar dalam mengintegrasikan sumber energi terbarukan seperti angin dan surya ke jaringan adalah...','[{"key": "A", "text": "Biaya bahan bakar yang tinggi."}, {"key": "B", "text": "Sifatnya yang intermiten (tidak kontinu) dan sulit diprediksi."}, {"key": "C", "text": "Emisi karbon yang dihasilkan."}, {"key": "D", "text": "Kebutuhan lahan yang sedikit."}]'::jsonb,'B','Jaringan listrik membutuhkan keseimbangan presisi antara pasokan dan permintaan. Sumber energi terbarukan seperti surya dan angin memiliki output yang berfluktuasi dan sulit diprediksi. Fluktuasi ini dapat menyebabkan ketidakstabilan frekuensi dan tegangan pada jaringan.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Komponen dalam sistem PLTS yang berfungsi untuk mengatur pengisian daya ke baterai agar tidak berlebih (overcharge) atau kosong (deep discharge) adalah...','[{"key": "A", "text": "Inverter."}, {"key": "B", "text": "Panel Surya."}, {"key": "C", "text": "Solar Charge Controller."}, {"key": "D", "text": "Kabel PV."}]'::jsonb,'C','Pada sistem PLTS yang menggunakan baterai, Solar Charge Controller (SCC) adalah komponen vital. Fungsinya adalah mengatur arus dan tegangan dari panel surya yang menuju ke baterai untuk mencegah pengisian berlebih (overcharging) atau pengosongan berlebih (deep discharging).','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PUIL (Persyaratan Umum Instalasi Listrik) bertujuan untuk...','[{"key": "A", "text": "Menentukan tarif dasar listrik."}, {"key": "B", "text": "Menjamin keselamatan manusia, keandalan instalasi, dan keamanan aset."}, {"key": "C", "text": "Mendorong penggunaan peralatan listrik merek tertentu."}, {"key": "D", "text": "Mengatur jadwal pemadaman listrik."}]'::jsonb,'B','PUIL adalah standar teknis acuan di Indonesia untuk perancangan dan pemasangan instalasi listrik. Tujuannya adalah untuk memastikan instalasi tersebut aman bagi pengguna, andal dalam pengoperasiannya, dan tidak membahayakan aset.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'ELCB (Earth Leakage Circuit Breaker) atau GFCI bekerja dengan mendeteksi...','[{"key": "A", "text": "Kenaikan suhu pada kabel."}, {"key": "B", "text": "Tegangan lebih pada sirkuit."}, {"key": "C", "text": "Arus hubung singkat yang sangat besar."}, {"key": "D", "text": "Adanya ketidakseimbangan antara arus yang pergi dan kembali (arus bocor ke tanah)."}]'::jsonb,'D','','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Komponen sistem proteksi petir eksternal yang berfungsi untuk menangkap sambaran petir secara langsung adalah...','[{"key": "A", "text": "Konduktor penyalur (down conductor)."}, {"key": "B", "text": "Terminal udara (air terminal / finial)."}, {"key": "C", "text": "Elektroda pentanahan (grounding electrode)."}, {"key": "D", "text": "Equipotential bonding."}]'::jsonb,'A','ELCB (atau nama modernnya RCCB/GFCI) bekerja dengan prinsip Hukum Arus Kirchhoff. Ia memiliki transformator arus kecil yang melingkupi kabel fasa dan netral. Dalam kondisi normal, arus yang pergi (lewat fasa) sama dengan arus yang kembali (lewat netral), sehingga medan magnet totalnya nol. Jika ada arus yang bocor ke tanah (misalnya melalui tubuh manusia), terjadi ketidakseimbangan yang dideteksi oleh transformator dan langsung memerintahkan pemutus untuk trip.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proteksi ground fault sangat penting karena...','[{"key": "A", "text": "Melindungi peralatan dari tegangan rendah."}, {"key": "B", "text": "Mencegah kebakaran dan sengatan listrik akibat arus bocor ke tanah."}, {"key": "C", "text": "Meningkatkan faktor daya sistem."}, {"key": "D", "text": "Menjaga frekuensi sistem tetap stabil."}]'::jsonb,'B','','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Relay jarak (distance relay) melindungi saluran transmisi dengan mengukur...','[{"key": "A", "text": "Suhu konduktor."}, {"key": "B", "text": "Waktu tempuh gelombang listrik."}, {"key": "C", "text": "Impedansi saluran hingga titik gangguan."}, {"key": "D", "text": "Perbedaan fasa antara dua ujung saluran."}]'::jsonb,'A','Sistem proteksi petir eksternal memiliki tiga komponen utama:','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Komponen elektronika yang berfungsi untuk menyimpan energi dalam bentuk medan listrik adalah...','[{"key": "A", "text": "Resistor."}, {"key": "B", "text": "Induktor."}, {"key": "C", "text": "Kapasitor."}, {"key": "D", "text": "Dioda."}]'::jsonb,'A','','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan karakteristik dari Operational Amplifier (Op-Amp) ideal?','[{"key": "A", "text": "Gain tegangan tak terhingga (infinite voltage gain)."}, {"key": "B", "text": "Impedansi input nol (zero input impedance)."}, {"key": "C", "text": "Impedansi output tak terhingga (infinite output impedance)."}, {"key": "D", "text": "Bandwidth yang terbatas (limited bandwidth)."}]'::jsonb,'A','','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rangkaian filter yang hanya melewatkan sinyal dengan frekuensi di bawah frekuensi cut-off tertentu disebut...','[{"key": "A", "text": "High-pass filter."}, {"key": "B", "text": "Low-pass filter."}, {"key": "C", "text": "Band-pass filter."}, {"key": "D", "text": "Band-stop filter."}]'::jsonb,'A','','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gain tegangan dari sebuah penguat pembalik (inverting amplifier) dengan Op-Amp ditentukan oleh perbandingan...','[{"key": "A", "text": "Resistor input dan sumber tegangan."}, {"key": "B", "text": "Resistor umpan balik (feedback) dan resistor input."}, {"key": "C", "text": "Resistor umpan balik dan tegangan output."}, {"key": "D", "text": "Resistor input dan impedansi input Op-Amp."}]'::jsonb,'B','','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aplikasi umum dari MOSFET atau IGBT dalam sistem tenaga listrik modern adalah sebagai...','[{"key": "A", "text": "Sensor suhu."}, {"key": "B", "text": "Saklar statis berkecepatan tinggi dalam inverter atau konverter frekuensi."}, {"key": "C", "text": "Pengukur daya listrik."}, {"key": "D", "text": "Isolator tegangan tinggi."}]'::jsonb,'A','Ground fault terjadi ketika konduktor bertegangan menyentuh bagian yang seharusnya tidak bertegangan (misalnya bodi logam peralatan). Arus bocor ini mungkin tidak cukup besar untuk mengaktifkan proteksi arus lebih, tetapi sangat berbahaya jika disentuh manusia dan bisa menimbulkan panas yang cukup untuk memicu kebakaran. Proteksi ground fault dirancang untuk mendeteksi arus bocor yang kecil ini.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut Hukum Tegangan Kirchhoff (KVL), jumlah aljabar dari semua beda potensial (tegangan) dalam satu loop tertutup adalah...','[{"key": "A", "text": "sama dengan arus total"}, {"key": "B", "text": "tak terhingga"}, {"key": "C", "text": "nol"}, {"key": "D", "text": "sama dengan hambatan total"}]'::jsonb,'C','Ini adalah pernyataan dari Hukum Tegangan Kirchhoff (KVL). Hukum ini menyatakan bahwa dalam setiap lintasan tertutup (loop), jumlah aljabar dari semua kenaikan dan penurunan tegangan adalah sama dengan nol (∑V=0). Ini merupakan manifestasi dari hukum kekekalan energi.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah lampu pijar dengan hambatan 50 Ω dialiri arus sebesar 2','[{"key": "A", "text": "Berapa daya listrik yang didisipasikan oleh lampu tersebut?"}, {"key": "B", "text": "100 W"}, {"key": "C", "text": "200 W"}, {"key": "D", "text": "25 W"}]'::jsonb,'B','Soal ini menanyakan daya disipasi pada komponen resistif.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah resistor 12 Ω dihubungkan seri dengan kombinasi paralel dari resistor 6 Ω dan 3 Ω. Berapakah hambatan total dari rangkaian tersebut?','[{"key": "A", "text": "21 Ω"}, {"key": "B", "text": "9 Ω"}, {"key": "C", "text": "14 Ω"}, {"key": "D", "text": "18 Ω"}]'::jsonb,'A','','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kebalikan dari resistansi (hambatan) yang menunjukkan kemudahan suatu material untuk menghantarkan arus listrik disebut...','[{"key": "A", "text": "Reaktansi"}, {"key": "B", "text": "Impedansi"}, {"key": "C", "text": "Konduktansi"}, {"key": "D", "text": "Induktansi"}]'::jsonb,'A','','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah kawat tembaga pada suhu 20°C memiliki hambatan 2 Ω. Jika koefisien temperatur tembaga adalah 0.004 /°C, berapakah perkiraan hambatannya pada suhu 70°C?','[{"key": "A", "text": "2.4 Ω"}, {"key": "B", "text": "1.6 Ω"}, {"key": "C", "text": "2.0 Ω"}, {"key": "D", "text": "3.0 Ω"}]'::jsonb,'A','','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada sistem 3 fasa yang terhubung bintang (Y), bagaimana hubungan antara arus saluran ($I_L$) dan arus fasa ($I_f$)?','[{"key": "A", "text": "$I_L = \\sqrt{3} \\times I_f$"}, {"key": "B", "text": "$I_f = \\sqrt{3} \\times I_L$"}, {"key": "C", "text": "$I_L = I_f$"}, {"key": "D", "text": "$I_L = I_f / \\sqrt{3}$"}]'::jsonb,'A','','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah generator 3 fasa menyuplai beban dengan tegangan jala-jala 400 V dan arus jala-jala 50','[{"key": "A", "text": "Berapakah daya semu (apparent power) total yang disuplai oleh generator?"}, {"key": "B", "text": "20 kVA"}, {"key": "C", "text": "34.6 kVA"}, {"key": "D", "text": "60 kVA"}]'::jsonb,'C','Rangkaian ini adalah kombinasi seri dan paralel.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Apa yang diindikasikan oleh faktor daya (power factor) yang bernilai 1 (unity)?','[{"key": "A", "text": "Beban bersifat murni induktif."}, {"key": "B", "text": "Arus dan tegangan sefasa, dan tidak ada daya reaktif."}, {"key": "C", "text": "Beban bersifat murni kapasitif."}, {"key": "D", "text": "Daya nyata sama dengan daya reaktif."}]'::jsonb,'A','','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah beban industri memiliki daya nyata 80 kW dan faktor daya 0.8 tertinggal (lagging). Berapakah daya reaktif (Q) yang ditarik oleh beban tersebut?','[{"key": "A", "text": "100 kVAR"}, {"key": "B", "text": "80 kVAR"}, {"key": "C", "text": "60 kVAR"}, {"key": "D", "text": "64 kVAR"}]'::jsonb,'A','','AKDING',9);
