  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada sebuah transformator ideal, jika rasio lilitan primer terhadap sekunder adalah 4:1 dan arus yang mengalir di sisi primer adalah 5 A, berapakah arus di sisi sekunder?','[{"key": "A", "text": "1.25 A"}, {"key": "B", "text": "5 A"}, {"key": "C", "text": "10 A"}, {"key": "D", "text": "20 A"}]'::jsonb,'A','','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Selain sebagai pendingin, fungsi utama minyak pada transformator daya adalah sebagai...','[{"key": "A", "text": "Pelumas bagian bergerak."}, {"key": "B", "text": "Bahan bakar."}, {"key": "C", "text": "Media isolasi tegangan tinggi."}, {"key": "D", "text": "Pencegah korosi."}]'::jsonb,'A','','AKDING',12);
