  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Apakah tujuan utama dari tap changer pada transformator daya?','[{"key": "A", "text": "Mengubah frekuensi."}, {"key": "B", "text": "Mengatur tegangan output dengan mengubah rasio lilitan."}, {"key": "C", "text": "Mendinginkan transformator."}, {"key": "D", "text": "Mengukur arus beban."}]'::jsonb,'A','','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fenomena di mana arus AC cenderung mengalir lebih banyak di permukaan konduktor daripada di bagian tengahnya disebut...','[{"key": "A", "text": "Efek Ferranti"}, {"key": "B", "text": "Efek Korona"}, {"key": "C", "text": "Efek Kulit (Skin Effect)"}, {"key": "D", "text": "Efek Proximity"}]'::jsonb,'C','Konduktansi (G) adalah ukuran kemudahan arus listrik mengalir melalui suatu bahan. Ini adalah kebalikan matematis dari resistansi (R) dan memiliki satuan Siemens (S). Hubungannya adalah G=1/R.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Alasan utama mengapa listrik ditransmisikan pada tegangan sangat tinggi adalah untuk...','[{"key": "A", "text": "Meningkatkan kecepatan aliran listrik."}, {"key": "B", "text": "Mengurangi rugi-rugi daya ($I^2R$) pada saluran."}, {"key": "C", "text": "Menggunakan konduktor yang lebih besar."}, {"key": "D", "text": "Memudahkan pengukuran."}]'::jsonb,'A','Perubahan hambatan akibat perubahan suhu dihitung menggunakan rumus berikut.','AKDING',17);
