  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Relay diferensial bekerja berdasarkan prinsip perbandingan...','[{"key": "A", "text": "Tegangan antara dua titik."}, {"key": "B", "text": "Arus yang masuk dan keluar dari zona yang diproteksi."}, {"key": "C", "text": "Frekuensi sistem."}, {"key": "D", "text": "Impedansi terhadap jarak."}]'::jsonb,'C','Pada hubungan bintang (Y), kawat saluran (line) terhubung langsung secara seri dengan lilitan fasa. Oleh karena itu, arus yang mengalir di saluran sama persis dengan arus yang mengalir di fasa yang terhubung dengannya.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Relay Buchholz adalah perangkat proteksi mekanis yang digunakan secara khusus untuk mendeteksi gangguan internal pada...','[{"key": "A", "text": "Generator"}, {"key": "B", "text": "Saluran transmisi"}, {"key": "C", "text": "Transformator berpendingin minyak"}, {"key": "D", "text": "Motor listrik"}]'::jsonb,'B','Soal ini menanyakan daya semu (S) untuk sistem 3 fasa.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan sistem proteksi untuk menyeleksi dan memisahkan hanya bagian sistem yang terganggu, tanpa menyebabkan pemadaman pada bagian yang sehat, disebut...','[{"key": "A", "text": "Sensitivitas"}, {"key": "B", "text": "Kecepatan"}, {"key": "C", "text": "Stabilitas"}, {"key": "D", "text": "Selektivitas (Koordinasi)"}]'::jsonb,'A','','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi dari lightning arrester yang dipasang pada peralatan gardu induk adalah...','[{"key": "A", "text": "Menangkap sambaran petir."}, {"key": "B", "text": "Menyediakan jalur berimpedansi rendah ke tanah untuk tegangan surja berlebih."}, {"key": "C", "text": "Memutuskan sirkuit saat terjadi petir."}, {"key": "D", "text": "Mengukur jumlah sambaran petir."}]'::jsonb,'A','','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tingkat keandalan sistem tenaga listrik sering diukur dengan indeks seperti SAIDI (System Average Interruption Duration Index), yang merepresentasikan...','[{"key": "A", "text": "Jumlah rata-rata pemadaman per pelanggan."}, {"key": "B", "text": "Durasi rata-rata pemadaman per pelanggan."}, {"key": "C", "text": "Frekuensi rata-rata pemadaman."}, {"key": "D", "text": "Total energi yang tidak tersalurkan."}]'::jsonb,'A','','AKDING',25);
