  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Selain turbin dan generator, komponen pada sistem PLTB yang berfungsi untuk mengarahkan turbin agar selalu menghadap arah datangnya angin adalah...','[{"key": "A", "text": "Gearbox"}, {"key": "B", "text": "Sistem Yaw"}, {"key": "C", "text": "Sistem Pitch"}, {"key": "D", "text": "Anemometer"}]'::jsonb,'B','Faktor daya adalah kosinus dari sudut fasa antara tegangan dan arus (cos(ϕ)). Jika nilainya 1, maka sudut fasa (ϕ) adalah 0 derajat. Ini berarti gelombang arus dan tegangan berada dalam satu fasa, yang terjadi pada beban resistif murni. Dalam kondisi ini, tidak ada daya reaktif (Q=0) dan daya semu (S) sama dengan daya nyata (P).','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'"Capacity Factor" dari sebuah pembangkit listrik (khususnya EBT) didefinisikan sebagai rasio antara...','[{"key": "A", "text": "Produksi energi aktual dalam setahun terhadap produksi energi maksimum teoritis."}, {"key": "B", "text": "Daya terpasang terhadap daya rata-rata."}, {"key": "C", "text": "Biaya operasi terhadap pendapatan."}, {"key": "D", "text": "Efisiensi maksimum terhadap efisiensi rata-rata."}]'::jsonb,'C','Perhitungan ini menggunakan konsep segitiga daya.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Bagaimana sebuah Battery Energy Storage System (BESS) dapat membantu menstabilkan frekuensi jaringan?','[{"key": "A", "text": "Dengan menyerap daya saat frekuensi terlalu tinggi dan menyuplai daya saat frekuensi terlalu rendah."}, {"key": "B", "text": "Dengan menghasilkan daya reaktif."}, {"key": "C", "text": "Dengan menurunkan tegangan jaringan."}, {"key": "D", "text": "Dengan meningkatkan kapasitas transmisi."}]'::jsonb,'A','','AKDING',29);
