  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan dari prosedur Lock-Out/Tag-Out (LOTO) dalam pemeliharaan listrik adalah...','[{"key": "A", "text": "Untuk mencatat siapa yang melakukan pekerjaan."}, {"key": "B", "text": "Untuk memastikan sumber energi berbahaya terisolasi dan tidak dapat diaktifkan kembali secara tidak sengaja."}, {"key": "C", "text": "Untuk mempercepat pekerjaan pemeliharaan."}, {"key": "D", "text": "Untuk mengunci panel agar tidak dicuri."}]'::jsonb,'A','','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kode IP54 pada sebuah enclosure listrik menandakan bahwa enclosure tersebut...','[{"key": "A", "text": "Tahan direndam dalam air."}, {"key": "B", "text": "Sepenuhnya kedap debu dan tahan semprotan air dari segala arah."}, {"key": "C", "text": "Terlindungi dari debu dalam jumlah terbatas dan tahan terhadap percikan air dari segala arah."}, {"key": "D", "text": "Hanya untuk penggunaan dalam ruangan yang kering."}]'::jsonb,'A','','AKDING',34);
