  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama dari transistor (seperti BJT atau MOSFET) dalam rangkaian elektronika adalah sebagai...','[{"key": "A", "text": "Sumber tegangan."}, {"key": "B", "text": "Penyimpan muatan."}, {"key": "C", "text": "Penguat sinyal atau saklar elektronik."}, {"key": "D", "text": "Penyearah arus."}]'::jsonb,'A','Urutan fasa (misalnya R-S-T) menciptakan medan magnet putar di dalam motor induksi 3 fasa. Arah putaran medan magnet inilah yang menentukan arah putaran rotor motor. Membalik dua fasa mana pun (misalnya menjadi R-T-S) akan membalik arah putaran motor.','AKDING',37);
